namespace MyApp.Evals.Tests;

internal static class AgentChatClientFactory
{
    /// <summary>
    /// Resolves the same IChatClient the app uses, by building a minimal
    /// host that mirrors the app's DI registration.
    /// Detected: AddAzureOpenAIChatClient("chat", "gpt-4o-mini") at AppHost.cs:2
    /// </summary>
    public static IChatClient Create()
    {
        var builder = Host.CreateApplicationBuilder();

        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);

        builder.AddAzureOpenAIChatClient("chat");
        var host = builder.Build();
        try
        {
            return host.Services.GetRequiredService<IChatClient>();
        }
        catch (InvalidOperationException ex)
        {
            throw new InvalidOperationException(
                "EVAL_USE_REAL_AGENT=1 but IChatClient could not be resolved. " +
                "The detected registration (AddAzureOpenAIChatClient) reads connection " +
                "string \"chat\" from configuration. Aspire's AppHost populates this at " +
                "runtime, but `dotnet test` runs standalone. Wire one of:\n" +
                "  # Key-based auth:\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;Key=<key>;DeploymentId=chat\" --project MyApp.Evals.Tests\n" +
                "  # Entra-ID auth (DefaultAzureCredential):\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;DeploymentId=chat\" --project MyApp.Evals.Tests\n",
                ex);
        }
    }
}

namespace MyApp.Evals.Tests;

internal sealed class StubChatClient : IChatClient
{
    public Task<ChatResponse> GetResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default)
    {
        var userMessage = messages.LastOrDefault(m => m.Role == ChatRole.User)?.Text ?? "";
        var stub = $"This is a stub response for evaluation. Input was: {userMessage}";
        return Task.FromResult(new ChatResponse(new ChatMessage(ChatRole.Assistant, stub))
        {
            ModelId = "stub",
            Usage = new UsageDetails { InputTokenCount = 10, OutputTokenCount = 20 }
        });
    }

    public IAsyncEnumerable<ChatResponseUpdate> GetStreamingResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default) =>
        throw new NotSupportedException("Streaming not supported in stub.");

    public object? GetService(Type serviceType, object? serviceKey = null) => null;

    public void Dispose() { }
}

internal static class Wire
{
    public static IChatClient ResolveAgentClient() =>
        EvalEnv.UseRealAgent ? AgentChatClientFactory.Create() : new StubChatClient();

    public static IChatClient ResolveJudgeClient(IChatClient agentClient) =>
        EvalEnv.UseRealJudge ? agentClient : new StubChatClient();
}

using System.Text.Json;

namespace MyApp.Evals.Tests;

public record TelemetryInput(string Agent, string Text);

internal static class InputsLoader
{
    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
        PropertyNameCaseInsensitive = true,
    };

    public static List<TelemetryInput> Load()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Telemetry", "inputs.json");
        return JsonSerializer.Deserialize<List<TelemetryInput>>(
            File.ReadAllText(path), s_options) ?? new();
    }
}

internal record TelemetryRecord(
    string AgentName, string Model, int InputTokens, int OutputTokens,
    long LatencyMs, decimal CostUsd);

internal static class TelemetryStore
{
    private static readonly List<TelemetryRecord> s_records = new();
    private static readonly object s_lock = new();

    public static void Record(TelemetryRecord r) { lock (s_lock) s_records.Add(r); }

    public static void FlushTo(string outDir)
    {
        Directory.CreateDirectory(outDir);
        var json = Path.Combine(outDir, "telemetry.json");
        var md = Path.Combine(outDir, "telemetry.md");

        lock (s_lock)
        {
            File.WriteAllText(json, JsonSerializer.Serialize(s_records,
                new JsonSerializerOptions { WriteIndented = true }));

            using var sw = new StreamWriter(md);
            sw.WriteLine("| Agent | Model | Input Tokens | Output Tokens | Latency (ms) | Cost (USD) |");
            sw.WriteLine("|-------|-------|-------------|--------------|-------------|-----------|");
            foreach (var r in s_records)
                sw.WriteLine($"| {r.AgentName} | {r.Model} | {r.InputTokens} | {r.OutputTokens} | {r.LatencyMs} | ${r.CostUsd:F6} |");
        }
        Console.WriteLine($"[Telemetry] {md}");
    }
}

internal sealed class PriceTable
{
    private readonly Dictionary<string, (decimal InputPer1k, decimal OutputPer1k)> _prices;

    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
        PropertyNameCaseInsensitive = true,
    };

    private PriceTable(Dictionary<string, (decimal, decimal)> prices) => _prices = prices;

    public static PriceTable Load()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Telemetry", "prices.json");
        using var doc = JsonDocument.Parse(File.ReadAllText(path));
        var dict = new Dictionary<string, (decimal, decimal)>(StringComparer.OrdinalIgnoreCase);
        foreach (var prop in doc.RootElement.EnumerateObject())
        {
            var inp = prop.Value.GetProperty("input_per_1k").GetDecimal();
            var outp = prop.Value.GetProperty("output_per_1k").GetDecimal();
            dict[prop.Name] = (inp, outp);
        }
        return new PriceTable(dict);
    }

    public decimal Cost(string? model, int inputTokens, int outputTokens)
    {
        if (model is null || !_prices.TryGetValue(model, out var p)) return 0m;
        return (inputTokens / 1000m * p.InputPer1k) + (outputTokens / 1000m * p.OutputPer1k);
    }
}

using System.Diagnostics;

namespace MyApp.Evals.Tests;

[TestClass]
public sealed class TelemetryTests
{
    public static IEnumerable<object[]> Inputs() =>
        InputsLoader.Load().Select(i => new object[] { i });

    [TestMethod, DynamicData(nameof(Inputs), DynamicDataSourceType.Method)]
    public async Task Capture(TelemetryInput input)
    {
        var inner = Wire.ResolveAgentClient();
        var prices = PriceTable.Load();

        var messages = new List<ChatMessage> { new(ChatRole.User, input.Text) };
        var sw = Stopwatch.StartNew();
        var response = await inner.GetResponseAsync(messages);
        sw.Stop();

        var usage = response.Usage;
        var cost = prices.Cost(response.ModelId,
            usage?.InputTokenCount ?? 0, usage?.OutputTokenCount ?? 0);

        TelemetryStore.Record(new TelemetryRecord(
            AgentName: input.Agent,
            Model: response.ModelId ?? "unknown",
            InputTokens: usage?.InputTokenCount ?? 0,
            OutputTokens: usage?.OutputTokenCount ?? 0,
            LatencyMs: sw.ElapsedMilliseconds,
            CostUsd: cost));
    }

    [ClassCleanup]
    public static void WriteReports() => TelemetryStore.FlushTo(
        Path.Combine(RepoRoot.Find(), ".copilot", "perf-reports", "evals",
                     EvalEnv.ReportFolder));
}

