+using System.Text.Json;
+
+namespace MyApp.Evals.Tests;
+
+public record TelemetryInput(string Agent, string Text);
+
+internal static class InputsLoader
+{
+    private static readonly JsonSerializerOptions s_options = new()
+    {
+        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
+        PropertyNameCaseInsensitive = true,
+    };
+
+    public static List<TelemetryInput> Load()
+    {
+        var path = Path.Combine(AppContext.BaseDirectory, "Telemetry", "inputs.json");
+        return JsonSerializer.Deserialize<List<TelemetryInput>>(
+            File.ReadAllText(path), s_options) ?? new();
+    }
+}
+
+internal record TelemetryRecord(
+    string AgentName, string Model, int InputTokens, int OutputTokens,
+    long LatencyMs, decimal CostUsd);
+
+internal static class TelemetryStore
+{
+    private static readonly List<TelemetryRecord> s_records = new();
+    private static readonly object s_lock = new();
+
+    public static void Record(TelemetryRecord r) { lock (s_lock) s_records.Add(r); }
+
+    public static void FlushTo(string outDir)
+    {
+        Directory.CreateDirectory(outDir);
+        var json = Path.Combine(outDir, "telemetry.json");
+        var md = Path.Combine(outDir, "telemetry.md");
+
+        lock (s_lock)
+        {
+            File.WriteAllText(json, JsonSerializer.Serialize(s_records,
+                new JsonSerializerOptions { WriteIndented = true }));
+
+            using var sw = new StreamWriter(md);
+            sw.WriteLine("| Agent | Model | Input Tokens | Output Tokens | Latency (ms) | Cost (USD) |");
+            sw.WriteLine("|-------|-------|-------------|--------------|-------------|-----------|");
+            foreach (var r in s_records)
+                sw.WriteLine($"| {r.AgentName} | {r.Model} | {r.InputTokens} | {r.OutputTokens} | {r.LatencyMs} | ${r.CostUsd:F6} |");
+        }
+        Console.WriteLine($"[Telemetry] {md}");
+    }
+}
+
+internal sealed class PriceTable
+{
+    private readonly Dictionary<string, (decimal InputPer1k, decimal OutputPer1k)> _prices;
+
+    private static readonly JsonSerializerOptions s_options = new()
+    {
+        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
+        PropertyNameCaseInsensitive = true,
+    };
+
+    private PriceTable(Dictionary<string, (decimal, decimal)> prices) => _prices = prices;
+
+    public static PriceTable Load()
+    {
+        var path = Path.Combine(AppContext.BaseDirectory, "Telemetry", "prices.json");
+        using var doc = JsonDocument.Parse(File.ReadAllText(path));
+        var dict = new Dictionary<string, (decimal, decimal)>(StringComparer.OrdinalIgnoreCase);
+        foreach (var prop in doc.RootElement.EnumerateObject())
+        {
+            var inp = prop.Value.GetProperty("input_per_1k").GetDecimal();
+            var outp = prop.Value.GetProperty("output_per_1k").GetDecimal();
+            dict[prop.Name] = (inp, outp);
+        }
+        return new PriceTable(dict);
+    }
+
+    public decimal Cost(string? model, int inputTokens, int outputTokens)
+    {
+        if (model is null || !_prices.TryGetValue(model, out var p)) return 0m;
+        return (inputTokens / 1000m * p.InputPer1k) + (outputTokens / 1000m * p.OutputPer1k);
+    }
+}
